SELECT  FROM ai_card_draft_source
WHERE owner_id=#{owner} AND source_item_id=#{itemId}
ORDER BY task_id,ordinal LIMIT #{limit}

SELECT  FROM ai_card_draft_source
WHERE owner_id=#{owner} AND task_id=#{taskId}
ORDER BY ordinal LIMIT #{limit}

SELECT owner_id,card_id,id,version_number AS number,card_kind AS kind,title,prompt_json,source_count,
  related_concept_count,created_at
FROM memory_card_version WHERE owner_id=#{owner} AND id=#{versionId}

SELECT owner_id,card_id,version_id,knowledge_item_id AS item_id,knowledge_version_id,position_index AS position
FROM memory_card_source WHERE owner_id=#{owner} AND version_id=#{versionId}
ORDER BY position_index LIMIT #{limit}
